--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
    raise debug 'PgBouncer auth request: %', p_usename;

    return query
    select 
        rolname::text, 
        case when rolvaliduntil < now() 
            then null 
            else rolpassword::text 
        end 
    from pg_authid 
    where rolname=$1 and rolcanlogin;
end;
$_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: next_invoice_number(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.next_invoice_number(fy text, p_prefix text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  seq_number INTEGER;
BEGIN
  INSERT INTO public.invoice_sequences (financial_year, prefix, next_number)
  VALUES (fy, p_prefix, 2)
  ON CONFLICT (financial_year, prefix)
  DO UPDATE SET next_number = public.invoice_sequences.next_number + 1
  RETURNING next_number - 1 INTO seq_number;

  RETURN p_prefix || '/' || fy || '/' || lpad(seq_number::text, 5, '0');
END;
$$;


ALTER FUNCTION public.next_invoice_number(fy text, p_prefix text) OWNER TO postgres;

