--
-- Name: v_puja_with_pandit_count; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_puja_with_pandit_count AS
 SELECT pu.id,
    pu.code,
    pu.title,
    pu.description,
    pu.category,
    pu.base_price,
    pu.shubh_available,
    pu.metadata,
    COALESCE(count_pp.pandit_count, (0)::bigint) AS pandit_count,
    COALESCE(min_price.min_price, pu.base_price) AS min_price
   FROM ((public.pujas pu
     LEFT JOIN ( SELECT pp.puja_id,
            count(DISTINCT pp.pandit_id) AS pandit_count
           FROM (public.pandit_puja pp
             JOIN public.pandits p ON (((p.id = pp.pandit_id) AND (p.is_active = true))))
          WHERE (pp.active = true)
          GROUP BY pp.puja_id) count_pp ON ((count_pp.puja_id = pu.id)))
     LEFT JOIN ( SELECT pp.puja_id,
            min(COALESCE(pp.price_override, p.price)) AS min_price
           FROM (public.pandit_puja pp
             JOIN public.pandits p ON (((p.id = pp.pandit_id) AND (p.is_active = true))))
          WHERE (pp.active = true)
          GROUP BY pp.puja_id) min_price ON ((min_price.puja_id = pu.id)));


ALTER VIEW public.v_puja_with_pandit_count OWNER TO postgres;

