001	{"create extension if not exists pgcrypto","create table if not exists public.pandits (\r\n  id uuid primary key default gen_random_uuid(),\r\n  name text not null,\r\n  languages text[] default array[]::text[],\r\n  experience integer default 0,\r\n  rating numeric(3,2) default 0,\r\n  price numeric(10,2) default 0,\r\n  approved boolean default false,\r\n  created_at timestamp with time zone default now()\r\n)","create table if not exists public.availability (\r\n  id uuid primary key default gen_random_uuid(),\r\n  puja_id integer not null,\r\n  date date not null,\r\n  timeslot text not null,\r\n  time text not null,\r\n  available boolean default true,\r\n  shubh boolean default false,\r\n  created_at timestamp with time zone default now()\r\n)","create table if not exists public.bookings (\r\n  id uuid primary key default gen_random_uuid(),\r\n  user_id integer not null,\r\n  puja_id integer not null,\r\n  package_id integer,\r\n  pandit_id uuid references public.pandits(id),\r\n  date date not null,\r\n  timeslot text not null,\r\n  amount numeric(10,2) not null,\r\n  payment_ref text,\r\n  status text not null default 'confirmed',\r\n  created_at timestamp with time zone default now()\r\n)","create table if not exists public.payment_sessions (\r\n  id uuid primary key default gen_random_uuid(),\r\n  session_id text not null unique,\r\n  amount numeric(10,2) not null,\r\n  currency text not null default 'INR',\r\n  method text not null default 'upi',\r\n  status text not null default 'initialized',\r\n  created_at timestamp with time zone default now()\r\n)","create index if not exists idx_availability_puja_date on public.availability (puja_id, date)","create index if not exists idx_bookings_user on public.bookings (user_id)","create index if not exists idx_bookings_pandit on public.bookings (pandit_id)"}	create_booking_tables
20260810090001	{"-- add_users_and_roles.sql\r\nCREATE EXTENSION IF NOT EXISTS \\"pgcrypto\\"","DO $$\r\nBEGIN\r\n  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'user_role') THEN\r\n    CREATE TYPE user_role AS ENUM ('user','pandit','admin');\r\n  END IF;\r\nEND$$","CREATE TABLE IF NOT EXISTS users (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  email TEXT NOT NULL UNIQUE,\r\n  password_hash TEXT NOT NULL,\r\n  full_name TEXT,\r\n  phone TEXT,\r\n  role user_role NOT NULL DEFAULT 'user',\r\n  metadata JSONB DEFAULT '{}'::jsonb,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  last_login TIMESTAMPTZ\r\n)","CREATE OR REPLACE FUNCTION trigger_set_timestamp()\r\nRETURNS TRIGGER AS $$\r\nBEGIN\r\n  NEW.updated_at = now();\r\n  RETURN NEW;\r\nEND;\r\n$$ LANGUAGE plpgsql","DROP TRIGGER IF EXISTS set_timestamp_users ON users","CREATE TRIGGER set_timestamp_users\r\nBEFORE UPDATE ON users\r\nFOR EACH ROW\r\nEXECUTE PROCEDURE trigger_set_timestamp()"}	add_users_and_roles
20260810090002	{"-- add_refresh_tokens.sql\r\nCREATE TABLE IF NOT EXISTS refresh_tokens (\r\n  id BIGSERIAL PRIMARY KEY,\r\n  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\r\n  token TEXT NOT NULL UNIQUE,\r\n  user_agent TEXT,\r\n  ip TEXT,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  expires_at TIMESTAMPTZ NOT NULL\r\n)","CREATE INDEX IF NOT EXISTS idx_refresh_tokens_user ON refresh_tokens(user_id)"}	add_refresh_tokens
20260810090003	{"-- add_audit_logs.sql\r\nCREATE TABLE IF NOT EXISTS audit_logs (\r\n  id BIGSERIAL PRIMARY KEY,\r\n  actor_id UUID,\r\n  action TEXT NOT NULL,\r\n  entity TEXT,\r\n  entity_id TEXT,\r\n  payload JSONB,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\r\n)","CREATE INDEX IF NOT EXISTS idx_audit_actor ON audit_logs(actor_id)","CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_logs(entity)"}	add_audit_logs
20260810090004	{"-- add_muhrats_and_referrals.sql\r\nCREATE TABLE IF NOT EXISTS muhrats (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  title TEXT,\r\n  description TEXT,\r\n  start_at TIMESTAMPTZ,\r\n  end_at TIMESTAMPTZ,\r\n  discount_percent NUMERIC,\r\n  active BOOLEAN DEFAULT FALSE,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\r\n)","DROP TRIGGER IF EXISTS set_timestamp_muhrats ON muhrats","CREATE TRIGGER set_timestamp_muhrats\r\nBEFORE UPDATE ON muhrats\r\nFOR EACH ROW\r\nEXECUTE PROCEDURE trigger_set_timestamp()","CREATE TABLE IF NOT EXISTS referrals (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  user_id UUID REFERENCES users(id) ON DELETE CASCADE,\r\n  code TEXT UNIQUE NOT NULL,\r\n  signup_reward NUMERIC DEFAULT 25,\r\n  booking_reward NUMERIC DEFAULT 51,\r\n  earnings NUMERIC DEFAULT 0,\r\n  total_earned NUMERIC DEFAULT 0,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\r\n)","DROP TRIGGER IF EXISTS set_timestamp_referrals ON referrals","CREATE TRIGGER set_timestamp_referrals\r\nBEFORE UPDATE ON referrals\r\nFOR EACH ROW\r\nEXECUTE PROCEDURE trigger_set_timestamp()"}	add_muhrats_and_referrals
20260810090005	{"-- add_bookings.sql\r\nCREATE TABLE IF NOT EXISTS bookings (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  user_id UUID REFERENCES users(id),\r\n  puja_id UUID,\r\n  pandit_id UUID,\r\n  package_id UUID,\r\n  date DATE,\r\n  timeslot TEXT,\r\n  amount NUMERIC,\r\n  payment_ref TEXT,\r\n  status TEXT,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\r\n)","DROP TRIGGER IF EXISTS set_timestamp_bookings ON bookings","CREATE TRIGGER set_timestamp_bookings\r\nBEFORE UPDATE ON bookings\r\nFOR EACH ROW\r\nEXECUTE PROCEDURE trigger_set_timestamp()"}	add_bookings
20260810090006	{"-- add_pujas_pandits.sql\r\nCREATE EXTENSION IF NOT EXISTS \\"pgcrypto\\"","CREATE OR REPLACE FUNCTION trigger_set_timestamp()\r\nRETURNS TRIGGER AS $$\r\nBEGIN\r\n  NEW.updated_at = now();\r\n  RETURN NEW;\r\nEND;\r\n$$ LANGUAGE plpgsql","CREATE TABLE IF NOT EXISTS pujas (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  code TEXT UNIQUE,\r\n  title TEXT NOT NULL,\r\n  description TEXT,\r\n  duration_minutes INTEGER,\r\n  base_price NUMERIC,\r\n  category TEXT,\r\n  shubh_available BOOLEAN DEFAULT FALSE,\r\n  metadata JSONB DEFAULT '{}'::jsonb,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\r\n)","DROP TRIGGER IF EXISTS set_timestamp_pujas ON pujas","CREATE TRIGGER set_timestamp_pujas\r\nBEFORE UPDATE ON pujas\r\nFOR EACH ROW\r\nEXECUTE PROCEDURE trigger_set_timestamp()","CREATE TABLE IF NOT EXISTS pandits (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID UNIQUE REFERENCES users(id) ON DELETE CASCADE,\n  display_name TEXT,\n  languages TEXT[],\n  experience_years INTEGER,\n  rating NUMERIC(2,1) DEFAULT 0,\n  price NUMERIC,\n  about TEXT,\n  avatar_url TEXT,\n  address TEXT,\n  city TEXT,\n  pin TEXT,\n  latitude NUMERIC,\n  longitude NUMERIC,\n  is_active BOOLEAN DEFAULT TRUE,\n  metadata JSONB DEFAULT '{}'::jsonb,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n)","DROP TRIGGER IF EXISTS set_timestamp_pandits ON pandits","CREATE TRIGGER set_timestamp_pandits\nBEFORE UPDATE ON pandits\nFOR EACH ROW\nEXECUTE PROCEDURE trigger_set_timestamp()","-- CREATE INDEX IF NOT EXISTS idx_pandits_city ON pandits(city); (commented temporarily)\n-- CREATE INDEX IF NOT EXISTS idx_pandits_is_active ON pandits(is_active); (commented temporarily)\r\nDO $$\nBEGIN\n  IF EXISTS (\n    SELECT 1 FROM information_schema.columns\n    WHERE table_name = 'pandits' AND column_name = 'city'\n  ) THEN\n    EXECUTE 'CREATE INDEX IF NOT EXISTS idx_pandits_city ON pandits(city)';\n  END IF;\nEND;\n$$","DO $$\nBEGIN\n  IF EXISTS (\n    SELECT 1 FROM information_schema.columns\n    WHERE table_name = 'pandits' AND column_name = 'is_active'\n  ) THEN\n    EXECUTE 'CREATE INDEX IF NOT EXISTS idx_pandits_is_active ON pandits(is_active)';\n  END IF;\nEND;\n$$"}	add_pujas_pandits
20260810090007	{"-- add_pandit_puja_relation.sql\r\nCREATE TABLE IF NOT EXISTS pandit_puja (\r\n  id BIGSERIAL PRIMARY KEY,\r\n  pandit_id UUID NOT NULL REFERENCES pandits(id) ON DELETE CASCADE,\r\n  puja_id UUID NOT NULL REFERENCES pujas(id) ON DELETE CASCADE,\r\n  price_override NUMERIC,\r\n  featured BOOLEAN DEFAULT FALSE,\r\n  active BOOLEAN DEFAULT TRUE,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  UNIQUE (pandit_id, puja_id)\r\n)","DROP TRIGGER IF EXISTS set_timestamp_pandit_puja ON pandit_puja","CREATE TRIGGER set_timestamp_pandit_puja\r\nBEFORE UPDATE ON pandit_puja\r\nFOR EACH ROW\r\nEXECUTE PROCEDURE trigger_set_timestamp()","CREATE INDEX IF NOT EXISTS idx_pandit_puja_puja ON pandit_puja(puja_id)","CREATE INDEX IF NOT EXISTS idx_pandit_puja_pandit ON pandit_puja(pandit_id)"}	add_pandit_puja_relation
20260810090008	{"-- add_festivals.sql\r\nCREATE TABLE IF NOT EXISTS festivals (\r\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n  title TEXT NOT NULL,\r\n  description TEXT,\r\n  start_date DATE NOT NULL,\r\n  end_date DATE,\r\n  image_url TEXT,\r\n  highlight BOOLEAN DEFAULT FALSE,\r\n  metadata JSONB DEFAULT '{}'::jsonb,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\r\n)","DROP TRIGGER IF EXISTS set_timestamp_festivals ON festivals","CREATE TRIGGER set_timestamp_festivals\r\nBEFORE UPDATE ON festivals\r\nFOR EACH ROW\r\nEXECUTE PROCEDURE trigger_set_timestamp()","CREATE INDEX IF NOT EXISTS idx_festivals_start_date ON festivals(start_date)","CREATE INDEX IF NOT EXISTS idx_festivals_highlight ON festivals(highlight)"}	add_festivals
20260810090010	{"-- add_timeslots.sql\r\nCREATE TABLE IF NOT EXISTS timeslots (\r\n  id BIGSERIAL PRIMARY KEY,\r\n  pandit_id UUID NOT NULL REFERENCES pandits(id) ON DELETE CASCADE,\r\n  slot_date DATE NOT NULL,\r\n  slot_time TIME WITHOUT TIME ZONE NOT NULL,\r\n  available BOOLEAN NOT NULL DEFAULT TRUE,\r\n  shubh BOOLEAN NOT NULL DEFAULT FALSE,\r\n  metadata JSONB DEFAULT '{}'::jsonb,\r\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\r\n  UNIQUE (pandit_id, slot_date, slot_time)\r\n)","DROP TRIGGER IF EXISTS set_timestamp_timeslots ON timeslots","CREATE TRIGGER set_timestamp_timeslots\r\nBEFORE UPDATE ON timeslots\r\nFOR EACH ROW\r\nEXECUTE PROCEDURE trigger_set_timestamp()","CREATE INDEX IF NOT EXISTS idx_timeslots_pandit_date ON timeslots(pandit_id, slot_date)","CREATE INDEX IF NOT EXISTS idx_timeslots_date_available ON timeslots(slot_date) WHERE available = true"}	add_timeslots
20260810090011	{"-- Ensure pandits has expected columns before creating indexes/views\nALTER TABLE IF EXISTS pandits\n  ADD COLUMN IF NOT EXISTS is_active BOOLEAN DEFAULT TRUE","-- Ensure metadata exists (defensive; safe if already present)\nALTER TABLE IF EXISTS pandits\n  ADD COLUMN IF NOT EXISTS metadata JSONB DEFAULT '{}'::jsonb","-- Ensure pandits.metadata exists before creating GIN index (added automatically to avoid index errors)\nALTER TABLE IF EXISTS pandits\n  ADD COLUMN IF NOT EXISTS metadata JSONB DEFAULT '{}'::jsonb","-- add_search_indexes_and_view.sql\r\nCREATE EXTENSION IF NOT EXISTS \\"pg_trgm\\"","CREATE EXTENSION IF NOT EXISTS \\"pgcrypto\\"","CREATE INDEX IF NOT EXISTS idx_users_metadata_gin ON users USING gin (metadata)","CREATE INDEX IF NOT EXISTS idx_pandits_metadata_gin ON pandits USING gin (metadata)","CREATE INDEX IF NOT EXISTS idx_pujas_metadata_gin ON pujas USING gin (metadata)","CREATE INDEX IF NOT EXISTS idx_pujas_tsv_title_desc ON pujas USING GIN (\r\n  to_tsvector('simple', coalesce(title, '') || ' ' || coalesce(description, ''))\r\n)","CREATE INDEX IF NOT EXISTS idx_pujas_title_trgm ON pujas USING gin (title gin_trgm_ops)","CREATE INDEX IF NOT EXISTS idx_pujas_category_title ON pujas (category)\r\nWHERE category IS NOT NULL","CREATE OR REPLACE VIEW v_puja_with_pandit_count AS\nSELECT\n  pu.id,\n  pu.code,\n  pu.title,\n  pu.description,\n  pu.category,\n  pu.base_price,\n  pu.shubh_available,\n  pu.metadata,\n  COALESCE(count_pp.pandit_count, 0) AS pandit_count,\n  COALESCE(min_price.min_price, pu.base_price) AS min_price\nFROM pujas pu\nLEFT JOIN (\n  SELECT puja_id, COUNT(DISTINCT pandit_id) AS pandit_count\n  FROM pandit_puja pp\n  JOIN pandits p ON p.id = pp.pandit_id AND p.is_active = true\n  WHERE pp.active = true\n  GROUP BY puja_id\n) AS count_pp ON count_pp.puja_id = pu.id\nLEFT JOIN (\n  SELECT puja_id, MIN(COALESCE(price_override, p.price)) AS min_price\n  FROM pandit_puja pp\n  JOIN pandits p ON p.id = pp.pandit_id AND p.is_active = true\n  WHERE pp.active = true\n  GROUP BY puja_id\n) AS min_price ON min_price.puja_id = pu.id"}	add_search_indexes_and_view
20260810090012	{"-- Ensure pandits.user_id exists before RLS policies reference it\nALTER TABLE IF EXISTS pandits\n  ADD COLUMN IF NOT EXISTS user_id UUID","-- Add FK constraint if users table exists and constraint missing (safe / idempotent)\nDO $$\nBEGIN\n  -- If users table exists and the foreign key is missing, add it.\n  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'users') THEN\n    IF NOT EXISTS (\n      SELECT 1\n      FROM information_schema.table_constraints tc\n      JOIN information_schema.key_column_usage kcu ON tc.constraint_name = kcu.constraint_name\n      WHERE tc.table_name = 'pandits'\n        AND tc.constraint_type = 'FOREIGN KEY'\n        AND kcu.column_name = 'user_id'\n    ) THEN\n      EXECUTE 'ALTER TABLE pandits ADD CONSTRAINT pandits_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE';\n    END IF;\n  END IF;\nEND;\n$$","-- add_rls_policies_examples.sql\r\nALTER TABLE pandits ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"pandits_select_public\\" ON pandits\r\n  FOR SELECT\r\n  USING (is_active = true)","CREATE POLICY \\"pandits_select_owner_or_admin\\" ON pandits\r\n  FOR SELECT\r\n  USING (user_id::text = auth.uid()::text OR\r\n         (exists (select 1 from users u where u.id::text = auth.uid()::text and u.role = 'admin')))","CREATE POLICY \\"pandits_insert_owner\\" ON pandits\r\n  FOR INSERT\r\n  WITH CHECK (user_id::text = auth.uid()::text)","CREATE POLICY \\"pandits_update_owner_or_admin\\" ON pandits\r\n  FOR UPDATE\r\n  USING (user_id::text = auth.uid()::text OR\r\n         (exists (select 1 from users u where u.id::text = auth.uid()::text and u.role = 'admin')))\r\n  WITH CHECK (user_id::text = auth.uid()::text OR\r\n             (exists (select 1 from users u where u.id::text = auth.uid()::text and u.role = 'admin')))","ALTER TABLE bookings ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"bookings_select_owner\\" ON bookings\r\n  FOR SELECT\r\n  USING (user_id::text = auth.uid()::text)","CREATE POLICY \\"bookings_insert_owner\\" ON bookings\r\n  FOR INSERT\r\n  WITH CHECK (user_id::text = auth.uid()::text)","CREATE POLICY \\"bookings_admin_select_update_delete\\" ON bookings\r\n  FOR ALL\r\n  USING (exists (select 1 from users u where u.id::text = auth.uid()::text and u.role = 'admin'))","ALTER TABLE timeslots ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"timeslots_select_public\\" ON timeslots\r\n  FOR SELECT\r\n  USING (available = true)","CREATE POLICY \\"timeslots_manage_owner\\" ON timeslots\r\n  FOR ALL\r\n  USING (pandit_id = (select id from pandits where user_id::text = auth.uid()::text))\r\n  WITH CHECK (pandit_id = (select id from pandits where user_id::text = auth.uid()::text) OR\r\n              (exists (select 1 from users u where u.id::text = auth.uid()::text and u.role = 'admin')))"}	add_rls_policies_examples
20260810090013	{"-- seed_timeslots_example.sql\n-- Replaced with a no-op because the original file contained invalid empty time literals (time '').\n-- This file is intentionally empty to allow database reset to complete.\n-- To add example timeslots, either:\n--  - ask me to generate a new migration that inserts valid timeslots, or\n--  - create a new seed migration that inserts rows with valid time values (e.g. '08:00','11:00','14:00','17:00')."}	seed_timeslots_example
