20260810234625	{"-- fix_pandits_add_missing_columns.sql\n-- Adds any missing columns and indexes to the pandits table safely (IF NOT EXISTS).\nALTER TABLE IF EXISTS pandits\n  ADD COLUMN IF NOT EXISTS user_id UUID UNIQUE,\n  ADD COLUMN IF NOT EXISTS display_name TEXT,\n  ADD COLUMN IF NOT EXISTS languages TEXT[],\n  ADD COLUMN IF NOT EXISTS experience_years INTEGER,\n  ADD COLUMN IF NOT EXISTS rating NUMERIC(2,1) DEFAULT 0,\n  ADD COLUMN IF NOT EXISTS price NUMERIC,\n  ADD COLUMN IF NOT EXISTS about TEXT,\n  ADD COLUMN IF NOT EXISTS avatar_url TEXT,\n  ADD COLUMN IF NOT EXISTS address TEXT,\n  ADD COLUMN IF NOT EXISTS city TEXT,\n  ADD COLUMN IF NOT EXISTS pin TEXT,\n  ADD COLUMN IF NOT EXISTS latitude NUMERIC,\n  ADD COLUMN IF NOT EXISTS longitude NUMERIC,\n  ADD COLUMN IF NOT EXISTS is_active BOOLEAN DEFAULT TRUE,\n  ADD COLUMN IF NOT EXISTS metadata JSONB DEFAULT '{}'::jsonb,\n  ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ DEFAULT now(),\n  ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT now()","-- Ensure foreign key exists for user_id (add constraint if missing)\nDO $$\nBEGIN\n  -- If trigger function exists and trigger missing, create it using separate EXECUTE statements\n  IF EXISTS (SELECT 1 FROM pg_catalog.pg_proc WHERE proname = 'trigger_set_timestamp') THEN\n    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'set_timestamp_pandits') THEN\n      EXECUTE 'DROP TRIGGER IF EXISTS set_timestamp_pandits ON pandits';\n      EXECUTE 'CREATE TRIGGER set_timestamp_pandits BEFORE UPDATE ON pandits FOR EACH ROW EXECUTE PROCEDURE trigger_set_timestamp()';\n    END IF;\n  END IF;\nEND;\n$$","-- Create indexes safely\nDO $$\nBEGIN\n  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='pandits' AND column_name='city') THEN\n    EXECUTE 'CREATE INDEX IF NOT EXISTS idx_pandits_city ON pandits(city)';\n  END IF;\n  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='pandits' AND column_name='is_active') THEN\n    EXECUTE 'CREATE INDEX IF NOT EXISTS idx_pandits_is_active ON pandits(is_active)';\n  END IF;\nEND;\n$$"}	fix_pandits_add_missing_columns
20260810234812	{"-- fix_pandits_add_missing_columns.sql\n-- Adds any missing columns and indexes to the pandits table safely (IF NOT EXISTS).\n\nALTER TABLE IF EXISTS pandits\n  ADD COLUMN IF NOT EXISTS user_id UUID UNIQUE,\n  ADD COLUMN IF NOT EXISTS display_name TEXT,\n  ADD COLUMN IF NOT EXISTS languages TEXT[],\n  ADD COLUMN IF NOT EXISTS experience_years INTEGER,\n  ADD COLUMN IF NOT EXISTS rating NUMERIC(2,1) DEFAULT 0,\n  ADD COLUMN IF NOT EXISTS price NUMERIC,\n  ADD COLUMN IF NOT EXISTS about TEXT,\n  ADD COLUMN IF NOT EXISTS avatar_url TEXT,\n  ADD COLUMN IF NOT EXISTS address TEXT,\n  ADD COLUMN IF NOT EXISTS city TEXT,\n  ADD COLUMN IF NOT EXISTS pin TEXT,\n  ADD COLUMN IF NOT EXISTS latitude NUMERIC,\n  ADD COLUMN IF NOT EXISTS longitude NUMERIC,\n  ADD COLUMN IF NOT EXISTS is_active BOOLEAN DEFAULT TRUE,\n  ADD COLUMN IF NOT EXISTS metadata JSONB DEFAULT '{}'::jsonb,\n  ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ DEFAULT now(),\n  ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT now()","-- Ensure foreign key exists for user_id (add constraint if missing)\nDO $$\nBEGIN\n  -- If trigger function exists and trigger missing, create it using separate EXECUTE statements\n  IF EXISTS (SELECT 1 FROM pg_catalog.pg_proc WHERE proname = 'trigger_set_timestamp') THEN\n    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'set_timestamp_pandits') THEN\n      EXECUTE 'DROP TRIGGER IF EXISTS set_timestamp_pandits ON pandits';\n      EXECUTE 'CREATE TRIGGER set_timestamp_pandits BEFORE UPDATE ON pandits FOR EACH ROW EXECUTE PROCEDURE trigger_set_timestamp()';\n    END IF;\n  END IF;\nEND;\n$$","-- Create indexes safely (only if column exists)\nDO $$\nBEGIN\n  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='pandits' AND column_name='city') THEN\n    EXECUTE 'CREATE INDEX IF NOT EXISTS idx_pandits_city ON pandits(city)';\n  END IF;\n  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='pandits' AND column_name='is_active') THEN\n    EXECUTE 'CREATE INDEX IF NOT EXISTS idx_pandits_is_active ON pandits(is_active)';\n  END IF;\nEND;\n$$"}	fix_pandits_add_missing_columns
20260810234813	{"-- seed_pujas_pandits_festivals.sql\n-- NOTE: Run this AFTER the schema migrations above.\n\n-- 1) Insert sample pujas\nINSERT INTO pujas (code, title, description, duration_minutes, base_price, category, shubh_available)\nVALUES\n  ('GRAH_SHANTI', 'Grah Shanti', 'Home Grah Shanti ritual for peace & prosperity', 90, 1200, 'home', true),\n  ('SATYANARAYAN', 'Satyanarayan Puja', 'Satyanarayan puja for good fortune', 75, 1000, 'home', true),\n  ('HOMA', 'Homa / Yajna', 'Small havan / homa for blessings', 60, 1500, 'ceremony', false)\nON CONFLICT (code) DO NOTHING","-- 2) Create example pandit users (3)\nINSERT INTO users (email, password_hash, full_name, role, created_at)\nVALUES\n  ('pandit1@local.test', crypt('panditpass', gen_salt('bf')), 'Pandit Rajesh Sharma', 'pandit', now())\nON CONFLICT (email) DO NOTHING","INSERT INTO users (email, password_hash, full_name, role, created_at)\nVALUES\n  ('pandit2@local.test', crypt('panditpass', gen_salt('bf')), 'Pandit Vivek Mishra', 'pandit', now())\nON CONFLICT (email) DO NOTHING","INSERT INTO users (email, password_hash, full_name, role, created_at)\nVALUES\n  ('pandit3@local.test', crypt('panditpass', gen_salt('bf')), 'Pandit Dinesh Pathak', 'pandit', now())\nON CONFLICT (email) DO NOTHING","-- 3) Insert pandit profiles (set both name and display_name to satisfy NOT NULL)\nINSERT INTO pandits (name, display_name, languages, experience_years, rating, price, about, avatar_url, city, address, pin, latitude, longitude)\nVALUES\n  ('Pandit Rajesh Sharma','Pandit Rajesh Sharma', ARRAY['Hindi','English'], 12, 4.9, 2100, 'Experienced priest for Grah Shanti and Satyanarayan', NULL, 'Delhi', 'Kashmere Gate, Delhi', '110006', 28.66, 77.23),\n  ('Pandit Vivek Mishra','Pandit Vivek Mishra', ARRAY['Hindi'], 9, 4.8, 1800, 'Honourable pandit with vast experience', NULL, 'Delhi', 'Connaught Place, Delhi', '110001', 28.63, 77.21),\n  ('Pandit Dinesh Pathak','Pandit Dinesh Pathak', ARRAY['Hindi','Sanskrit'], 15, 4.7, 2500, 'Expert in Vedic rituals and homa', NULL, 'Delhi', 'Karol Bagh, Delhi', '110005', 28.65, 77.20)\nON CONFLICT DO NOTHING","-- 4) Map pandits to pujas by matching display_name -> pandit id\nINSERT INTO pandit_puja (pandit_id, puja_id, price_override, featured)\nSELECT p.id, pu.id, NULL, FALSE\nFROM pandits p JOIN pujas pu ON pu.code = 'GRAH_SHANTI'\nWHERE p.display_name ILIKE '%Rajesh%'\nON CONFLICT (pandit_id, puja_id) DO NOTHING","INSERT INTO pandit_puja (pandit_id, puja_id, price_override, featured)\nSELECT p.id, pu.id, NULL, TRUE\nFROM pandits p JOIN pujas pu ON pu.code = 'GRAH_SHANTI'\nWHERE p.display_name ILIKE '%Vivek%'\nON CONFLICT (pandit_id, puja_id) DO NOTHING","INSERT INTO pandit_puja (pandit_id, puja_id, price_override, featured)\nSELECT p.id, pu.id, 2800, FALSE\nFROM pandits p JOIN pujas pu ON pu.code = 'HOMA'\nWHERE p.display_name ILIKE '%Dinesh%'\nON CONFLICT (pandit_id, puja_id) DO NOTHING","-- 5) Insert sample upcoming festivals\nINSERT INTO festivals (title, description, start_date, end_date, image_url, highlight)\nVALUES\n  ('Diwali', 'Festival of lights — auspicious time for house pujas and rituals', date_trunc('day', now())::date + INTERVAL '45 day', NULL, NULL, TRUE),\n  ('Navaratri', 'Nine nights festival dedicated to Durga', date_trunc('day', now())::date + INTERVAL '120 day', date_trunc('day', now())::date + INTERVAL '129 day', NULL, FALSE),\n  ('Makar Sankranti', 'Harvest festival and holy dips', date_trunc('day', now())::date + INTERVAL '200 day', NULL, NULL, FALSE)\nON CONFLICT DO NOTHING"}	seed_pujas_pandits_festivals
