--
-- Name: bookings bookings_admin_select_update_delete; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY bookings_admin_select_update_delete ON public.bookings USING ((EXISTS ( SELECT 1
   FROM public.users u
  WHERE (((u.id)::text = (auth.uid())::text) AND (u.role = 'admin'::public.user_role)))));


--
-- Name: bookings bookings_insert_owner; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY bookings_insert_owner ON public.bookings FOR INSERT WITH CHECK ((client_id IN ( SELECT users.id
   FROM public.users
  WHERE (users.auth_uid = auth.uid()))));


--
-- Name: bookings bookings_select_owner; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY bookings_select_owner ON public.bookings FOR SELECT USING ((client_id IN ( SELECT users.id
   FROM public.users
  WHERE (users.auth_uid = auth.uid()))));


