--
-- Name: pandits pandits_insert_owner; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY pandits_insert_owner ON public.pandits FOR INSERT WITH CHECK (((user_id)::text = (auth.uid())::text));


--
-- Name: pandits pandits_select_owner_or_admin; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY pandits_select_owner_or_admin ON public.pandits FOR SELECT USING ((((user_id)::text = (auth.uid())::text) OR (EXISTS ( SELECT 1
   FROM public.users u
  WHERE (((u.id)::text = (auth.uid())::text) AND (u.role = 'admin'::public.user_role))))));


--
-- Name: pandits pandits_select_public; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY pandits_select_public ON public.pandits FOR SELECT USING ((is_active = true));


--
-- Name: pandits pandits_update_owner_or_admin; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY pandits_update_owner_or_admin ON public.pandits FOR UPDATE USING ((((user_id)::text = (auth.uid())::text) OR (EXISTS ( SELECT 1
   FROM public.users u
  WHERE (((u.id)::text = (auth.uid())::text) AND (u.role = 'admin'::public.user_role)))))) WITH CHECK ((((user_id)::text = (auth.uid())::text) OR (EXISTS ( SELECT 1
   FROM public.users u
  WHERE (((u.id)::text = (auth.uid())::text) AND (u.role = 'admin'::public.user_role))))));


