--
-- Name: timeslots timeslots_manage_owner; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY timeslots_manage_owner ON public.timeslots USING ((pandit_id = ( SELECT pandits.id
   FROM public.pandits
  WHERE ((pandits.user_id)::text = (auth.uid())::text)))) WITH CHECK (((pandit_id = ( SELECT pandits.id
   FROM public.pandits
  WHERE ((pandits.user_id)::text = (auth.uid())::text))) OR (EXISTS ( SELECT 1
   FROM public.users u
  WHERE (((u.id)::text = (auth.uid())::text) AND (u.role = 'admin'::public.user_role))))));


--
-- Name: timeslots timeslots_select_public; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY timeslots_select_public ON public.timeslots FOR SELECT USING ((available = true));


